#include "tigersheets/grid.hpp"
#include "tigersheets/calculation.hpp"
#include <QApplication>
#include <cmath>
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
namespace {void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
void averageFormat(){WorkbookSession session;WorksheetModel model(session);const std::string percentage="0.0%;(0.0%)";Json cells=Json::array();for(const auto [col,value]:{std::pair{3,"0.822"},std::pair{4,"0.826"},std::pair{5,"0.823"}})cells.push_back({{"type","set_cell"},{"sheet","sheet-1"},{"row",15},{"col",col},{"input",value},{"style",{{"numberFormat",percentage}}}});cells.push_back({{"type","set_style"},{"sheet","sheet-1"},{"row",15},{"col",6},{"style",{{"bold",true},{"color","#0000FF"}}}});require(model.apply(cells),"Create independently specified percentage inputs");const auto before=session.snapshot();require(model.setData(model.index(14,5),"=AVERAGE(C15:E15)",Qt::EditRole),"Enter source AVERAGE through the public worksheet entry interface");model.setCalculated(CalculationEngine().calculate(session.snapshotView()));require(std::abs(model.numericValue(14,5).value_or(-1)-(.822+.826+.823)/3)<1e-15,"AVERAGE retains its actual calculated numeric result");require(model.cellStyle(14,5).value("numberFormat",std::string())==percentage&&model.data(model.index(14,5)).toString()=="82.4%","General AVERAGE entry inherits the first actual range percentage format, as observed48:05");require(model.raw(14,5)=="=AVERAGE(C15:E15)"&&model.cellStyle(14,5).at("bold")==true&&model.cellStyle(14,5).at("color")=="#0000FF","Numeric display inference preserves formula, target emphasis and color");require(session.undo()&&session.snapshotView().at("sheets")==before.at("sheets"),"Inferred number format and formula are one undoable native entry");}
void costRowFormat(){
 const std::string money="$#,##0;($#,##0);-",cost="#,##0;(#,##0);-";
 for(int scenario=0;scenario<5;++scenario){WorkbookSession session;WorksheetModel model(session);Json operations=Json::array({{{"type","set_cell"},{"sheet","sheet-1"},{"row",28},{"col",6},{"input","6749"},{"style",{{"numberFormat",money}}}},{{"type","set_cell"},{"sheet","sheet-1"},{"row",15},{"col",6},{"input","0.824"},{"style",{{"numberFormat","0.0%"}}}}});
  for(int col=3;col<=5;++col){if(scenario==1&&col==3)continue;operations.push_back({{"type","set_cell"},{"sheet","sheet-1"},{"row",32},{"col",col},{"input",scenario==3&&col==5?"label":"-4640"},{"style",{{"numberFormat",scenario==2&&col==4?money:cost}}}});}
  operations.push_back({{"type","set_style"},{"sheet","sheet-1"},{"row",32},{"col",6},{"style",{{"color","#0000FF"},{"numberFormat",scenario==4?"0.00":"General"}}}});require(model.apply(operations),"Prepare actual neighboring numeric formats");const auto before=session.snapshot();require(model.setData(model.index(31,5),"=-F28*F15",Qt::EditRole),"Enter actual source cost formula with a leading unary minus");model.setCalculated(CalculationEngine().calculate(session.snapshotView()));const auto expected=scenario==0?cost:scenario==4?std::string("0.00"):money;
  require(model.cellStyle(31,5).value("numberFormat",std::string())==expected,"Three matching adjacent numeric cells extend their number format before reference inference; only two, mixed formats, text and explicit targets remain bounded");require(std::abs(model.numericValue(31,5).value_or(0)+6749*.824)<1e-11,"Row-format extension preserves the true calculated formula result");if(scenario==0)require(model.data(model.index(31,5)).toString()=="(5,561)","Cost row extension displays the negative value without a revenue dollar symbol");require(model.raw(31,5)=="=-F28*F15"&&model.cellStyle(31,5).at("color")=="#0000FF","Row pattern inference preserves formula text and unrelated target color");require(session.undo()&&session.snapshotView().at("sheets")==before.at("sheets"),"Row format and input are one native Undo transaction");
 }
}
}
int main(int argc,char** argv){QApplication app(argc,argv);try{averageFormat();costRowFormat();std::cout<<"Formula number-format inference passed\n";return 0;}catch(const std::exception& error){std::cerr<<"FAILED: "<<error.what()<<'\n';return 1;}}
